export const METERS_PER_MILE = 1609.344;

/** Returns the equivalent seconds per kilometre given seconds per mile. Returns null for non-positive or non-number values. */
export function secPerKm(secPerMile) {
  const s = finitePositive(secPerMile);
  if (!s) return null;
  return s / (METERS_PER_MILE / 1000);
}

