import { describe, expect, it } from "vitest";
import { secPerKm, formatPace, paceTarget, buildPaceZones } from "../runPaces";

describe("Running Pace Kilometre Support", () => {
  describe("secPerKm", () => {
    it("AC-7: should return equivalent seconds per kilometre for positive seconds per mile", () => {
      // 483 sec/mi is approx 300 sec/km (5:00/km)
      const result = secPerKm(483);
      expect(result).toBeCloseTo(300, 0);
      expect(typeof result).toBe("number");
    });

    it("AC-8: should return null for zero or negative values", () => {
      expect(secPerKm(0)).toBeNull();
      expect(secPerKm(-100)).toBeNull();
    });

    it("AC-8: should return null for non-number values", () => {
      expect(secPerKm("483")).toBeNull();
      expect(secPerKm(null)).toBeNull();
      expect(secPerKm(undefined)).toBeNull();
      expect(secPerKm({})).toBeNull();
    });
  });

  describe("formatPace", () => {
    it("AC-1: should return '5:00' when 483 sec/mi is formatted as km", () => {
      expect(formatPace(483, 'km')).toBe('5:00');
    });

    it("AC-2: should return pace formatted as minutes per mile when no unit is provided", () => {
      // 483 sec/mi = 8:03/mi
      expect(formatPace(483)).toBe('8:03');
    });

    it("AC-2: should return pace formatted as minutes per mile when unit is 'mi'", () => {
      expect(formatPace(483, 'mi')).toBe('8:03');
    });

    it("AC-3: should treat unknown units as 'mi' and return minutes per mile", () => {
      expect(formatPace(483, 'unknown')).toBe('8:03');
      expect(formatPace(483, 'meters')).toBe('8:03');
    });
  });

  describe("paceTarget", () => {
    // Use buildPaceZones to get a valid zones object as paceTarget expects
    const zones = buildPaceZones({ distance: "5k", seconds: 19 * 60 + 57 });
    const intensity = "threshold";

    it("AC-4: should return label containing kilometre paces and ending with '/km' when unit is 'km'", () => {
      const result = paceTarget(zones, intensity, 'km');
      expect(result.label).toMatch(/\d+:\d{2}\/km$/);
    });

    it("AC-5: should maintain numeric value in seconds per mile when unit is 'km'", () => {
      const result = paceTarget(zones, intensity, 'km');
      // Result should still be in secPerMile (e.g., thresholds for a 19:57 5k are significantly higher than 300)
      expect(result.secPerMile).toBe(zones.threshold);
    });

    it("AC-6: should use mile-based formatting in label when no unit is provided", () => {
      const result = paceTarget(zones, intensity);
      expect(result.label).toMatch(/\d+:\d{2}\/mi$/);
    });
  });
});

